/**
 * The app's `_headers` as a build serves it: the committed
 * `public/_headers.base` plus the one rule a build flag adds.
 *
 * One composition with two callers: `generate-seo.mjs`, which writes the
 * gitignored `public/_headers` for the build, and the keyless live drive
 * `e2e/live/live-robots-headers.mjs`, which checks the deployed site
 * against the same policy. The drive must not read the generated file —
 * it exists only in a checkout that has built, and reflects whatever
 * flags that build had.
 */
import { readFileSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));

/** The committed base file. */
export function readHeadersBase() {
  return readFileSync(resolve(__dirname, '..', 'public', '_headers.base'), 'utf8');
}

/**
 * ONE rule is build-dependent and it cannot live in a static file: with
 * `VITE_ADMIN_DASHBOARD_PUBLIC=false` the console renders only its
 * hidden-state message, but `SeoMeta`'s noindex is a React decision, so
 * a crawler that does not execute JavaScript received an indexable HTTP
 * 200 for the surface the deployment had chosen to withhold. `_headers`
 * covered `/protocol-console/*` — the soft-404 children — and not the
 * exact route, which is the one that actually serves the page.
 *
 * When the console IS public (the default, and the retail deploy) the
 * route must stay indexable, so the rule cannot simply be added to the
 * base file.
 *
 * @param {string} base the committed `_headers.base`
 * @param {{ consolePublic: boolean }} flags
 */
export function composeHeaders(base, { consolePublic }) {
  if (consolePublic) return base;
  return (
    base.replace(/\n*$/, '\n') +
    '\n# Generated by scripts/generate-seo.mjs —' +
    ' VITE_ADMIN_DASHBOARD_PUBLIC=false on this build.\n' +
    '# The EXACT route, which `/protocol-console/*` does not cover: the\n' +
    '# page renders only its hidden-state message here, and a crawler\n' +
    '# that does not run JS would otherwise index it from the 200 shell.\n' +
    '/protocol-console\n' +
    '  X-Robots-Tag: noindex\n'
  );
}
